isc.BizUtil.addClassMethods({
	_currentView: null, // The view currently displayed

	/**
	 * Gets the current view.
	 * @returns {Object} - The current view.
	 */
	getCurrentView: function () {
		return isc.BizUtil._currentView;
	},

	/**
	 * Checks if a field type is numeric.
	 * @param {string} type - the field type.
	 * @returns {boolean} - true if the field type is numeric.
	 */
	isNumeric: function (type) {
		const numericTypes = [
			"integer",
			"float",
			"bizDecimal0",
			"bizDecimal1",
			"bizDecimal10",
			"bizDecimal2",
			"bizDecimal5",
			"bizDollarsAndCents",
			"bizDollarsAndCentsAbsolute",
			"bizIntegerPercentage",
			"bizIntegerSeparator",
			"bizSimplePercentage",
			"bizTwoDecimalPlacesPercentage",
			"bizTimeDuration",
		];
		return numericTypes.includes(type);
	},

	/**
	 * Checks if a field type is temporal.
	 * @param {string} type - the field type.
	 * @returns {boolean} - true if the field type is temporal.
	 */
	isTemporal: function (type) {
		const temporalTypes = [
			"date",
			"time",
			"datetime",
			"bizDate",
			"bizTime",
			"DD_MM",
			"MM_DD",
			"MMM_DD",
			"YYYY_MM",
			"HH_MI",
			"HH24_MI",
		];
		return temporalTypes.some((temporalType) => type.startsWith(temporalType));
	},

	/**
	 * Adds filter request parameters.
	 * @param {Object} requestParams - the request parameters to populate.
	 * @param {Array} filterParams - the filter parameters.
	 * @param {Object} view - the associated view.
	 */
	addFilterRequestParams: function (requestParams, filterParams, view) {
		const instance = view.gather(false);
		filterParams.forEach((filterParam) => {
			const value = view.toDisplay(filterParam.value, instance);
			requestParams[filterParam.name] = value;
		});
	},

	/**
	 * Converts filter criteria by renaming `_display_*` fields, and by keeping time values as times.
	 * @param {Object} criteria - the criteria to convert.
	 */
	convertFilterCriteria: function (criteria) {
		if (criteria) {
			if (criteria.criteria) {
				criteria.criteria.forEach((criterion) =>
					isc.BizUtil.convertFilterCriteria(criterion),
				);
				return;
			}
			// SmartClient's FilterBuilder flags every Date in a clause as a logical date unless its field is a datetime,
			// so a time clause's value is sent as a date (1970-01-01). A Date flagged as both is a time: send it as one.
			["value", "start", "end"].forEach((name) => {
				const value = criteria[name];
				if (isc.isA.Date(value) && value.logicalTime && value.logicalDate) {
					delete value.logicalDate;
				}
			});
			if (
				criteria.fieldName &&
				criteria.fieldName.startsWith("_display_")
			) {
				criteria.fieldName = criteria.fieldName.substring(9);
			} else {
				Object.keys(criteria).forEach((propertyName) => {
					if (propertyName.startsWith("_display_")) {
						criteria[propertyName.substring(9)] = criteria[propertyName];
						delete criteria[propertyName];
					}
				});
			}
		}
	},

	/**
	 * Completes filter criteria by adding extra criteria from filterParams.
	 * @param {Object} criteria - the base criteria.
	 * @param {Array} filterParams - the filter parameters.
	 * @param {Object} view - the associated view.
	 * @returns {Object} - the completed criteria.
	 */
	completeFilterCriteria: function (criteria, filterParams, view) {
		let result = { ...criteria };
		if (!result.operator) {
			result = isc.DataSource.convertCriteria(result, "substring");
		}
		result = {
			_constructor: "AdvancedCriteria",
			operator: "and",
			criteria: [result],
		};

		const instance = view.gather(false);
		filterParams.forEach((filterParam) => {
			const value = view.toDisplay(filterParam.value, instance);
			result.criteria.push({
				fieldName: filterParam.name,
				operator: filterParam.operator,
				value,
			});
		});

		return result;
	},

	/**
	 * Creates an image button.
	 * @param {string} name - the button name (used for locator purposes).
	 * @param {string} icon - the icon path.
	 * @param {boolean} hasDisabledIcon - whether the button has a disabled icon.
	 * @param {string} tooltip - the button tooltip.
	 * @param {Function} click - the click handler.
	 * @returns {Object} - the created button.
	 */
	createImageButton: function (name, icon, hasDisabledIcon, tooltip, click) {
		return isc.ToolStripButton.create({
			name,
			icon,
			iconAlign: "center",
			showDisabledIcon: hasDisabledIcon,
			showDownIcon: false,
			canHover: true,
			getHoverHTML: () => tooltip,
			click,
		});
	},

	/**
	 * Creates a CodeMirror editor for syntax highlighting.
	 * @param {string} scVar - the smart client variable.
	 * @param {string} binding - the binding for the text area.
	 * @param {string} languageMimeType - the language mime type for syntax highlighting.
	 *
	 * @see https://codemirror.net/LICENSE
	 */
	createCodeMirror: function (scVar, binding, languageMimeType) {
		const loadResources = async () => {
			await SKYVE.Util.loadCSS(`codemirror/codemirror.css?v=${SKYVE.Util.v}`);
			await SKYVE.Util.loadCSS(`codemirror/base16-dark.css?v=${SKYVE.Util.v}`);
			await SKYVE.Util.loadJS(`codemirror/codemirror.js?v=${SKYVE.Util.v}`);
			await SKYVE.Util.loadJS(`codemirror/css/css.js?v=${SKYVE.Util.v}`);
			await SKYVE.Util.loadJS(
				`codemirror/htmlmixed/htmlmixed.js?v=${SKYVE.Util.v}`,
			);
			await SKYVE.Util.loadJS(`codemirror/sql/sql.js?v=${SKYVE.Util.v}`);
			await SKYVE.Util.loadJS(`codemirror/xml/xml.js?v=${SKYVE.Util.v}`);

			const templates = document.getElementsByName(binding);
			const templateElement =
				templates &&
				templates.length > 0 &&
				templates[0].nodeName.toLowerCase() === "textarea"
					? templates[0]
					: undefined;

			if (templateElement) {
				templateElement.setAttribute("autocapitalize", "off");
				templateElement.setAttribute("spellcheck", "false");

				const editor = CodeMirror.fromTextArea(templateElement, {
					mode: languageMimeType,
					lineNumbers: true,
					theme: "base16-dark",
				});
				editor.setSize(600, null);
				editor.on("change", () => editor.save());
			}
		};

		loadResources();
	},

	/**
	 * Creates a split button.
	 * @param {string} buttonTitle - the title of the main button.
	 * @param {string} buttonIcon - the icon for the main button.
	 * @param {boolean} buttonHasDisabledIcon - whether the main button has a disabled icon.
	 * @param {string} buttonTooltip - the tooltip for the main button.
	 * @param {Function} buttonClick - the click handler for the main button.
	 * @param {string} splitTooltip - the tooltip for the split button.
	 * @param {Object} splitTarget - the target for the split button.
	 * @param {Array} splitItems - the menu items for the split button.
	 * @param {number|string} [width] - optional width for the surrounding layout.
	 * @param {string} [align='right'] - member alignment for the surrounding layout.
	 * @returns {Object} - the created split button.
	 */
	createSplitButton: function (
		buttonTitle,
		buttonIcon,
		buttonHasDisabledIcon,
		buttonTooltip,
		buttonClick,
		splitTooltip,
		splitTarget,
		splitItems,
		width,
		align,
	) {
		return isc.HLayout.create({
			align: align || "right",
			height: 1,
			membersMargin: 1,
			width: width,
			members: [
				isc.IButton.create({
					autoFit: true,
					title: buttonTitle,
					icon: buttonIcon,
					showDisabledIcon: buttonHasDisabledIcon,
					canHover: true,
					getHoverHTML: () => buttonTooltip,
					click: buttonClick,
				}),
				isc.MenuButton.create({
					title: null,
					width: 26,
					alignMenuLeft: false,
					canHover: true,
					getHoverHTML: () => splitTooltip,
					menu: isc.Menu.create({
						autoDraw: false,
						showShadow: true,
						shadowDepth: 10,
						target: splitTarget,
						data: splitItems,
						show: function () {
							const data = this.getAllItems();
							for (let i = 0, l = data.length; i < l; i++) {
								const item = this.getItem(i, true);
								if (item && item.hiddenIf) {
									isc.Func.replaceWithMethod(item, "hiddenIf", "target,menu,item");
									this.setItemHidden(i, item.hiddenIf(this.target, this, item));
								}
							}
							return this.Super("show", arguments);
						},
					}),
				}),
			],
		});
	},

	createContentUploadUrl: function (contentFormItem, image) {
		const instance = contentFormItem.form._view.gather(false);
		const display = contentFormItem.display || (image ? "image" : "link");
		const capture = contentFormItem.capture || "none";
		let url = `upload.xhtml?_u=boundContent&_n=${SKYVE.Util.unsanitiseBinding(
			contentFormItem.name,
		)}&_c=${instance._c}&_d=${display}&_cap=${capture}`;
		if (contentFormItem.form._view._b) {
			url += `&_b=${SKYVE.Util.unsanitiseBinding(contentFormItem.form._view._b)}`;
		}
		if (contentFormItem.companion) {
			url += `&_m=${contentFormItem.companion}`;
		}
		return url;
	},

	openContentUpload: function (contentFormItem, image, uploadNoun) {
		isc.BizUtil._registerContentFormItem(contentFormItem);
		const url = isc.BizUtil.createContentUploadUrl(contentFormItem, image);
		const messageSuffix = isc.BizUtil._contentUploadMessageSuffix(
			uploadNoun,
			image,
		);
		isc.WindowStack.popup(
			null,
			isc.i18nMessages[
				"bizUtilSplitButton_UploadPopup" + messageSuffix + "Title"
			],
			true,
			[
				isc.HTMLPane.create({
					contentsType: "page",
					contents: "Loading Page...",
					contentsURL: url,
				}),
			],
		);
	},

	_contentUploadMessageSuffix: function (uploadNoun, image) {
		const noun = uploadNoun || (image ? "Image" : "Content");
		if (noun === "Image" || noun === "Video") {
			return noun;
		}
		return "Content";
	},

	_registerContentFormItem: function (contentFormItem) {
		isc.BizUtil._contentFormItemsByBinding[contentFormItem.name] =
			contentFormItem;
	},

	_getContentFormItem: function (binding) {
		let result = isc.BizUtil._contentFormItemsByBinding[binding];
		if (!result) {
			const opener = isc.WindowStack.getOpener();
			if (opener && opener._vm) {
				result = opener._vm.getItem(binding);
			}
		}
		return result;
	},

	_setContentFormItemValue: function (contentFormItem, contentId, mediaKind) {
		const view = contentFormItem.form._view;
		if (mediaKind && contentFormItem.companion) {
			view._vm.setValue(contentFormItem.companion, mediaKind);
		}
		view._vm.setValue(contentFormItem.name, contentId);
	},

	afterContentUpload: function (
		binding,
		contentId,
		modoc,
		fileName,
		mediaKind,
		companionBinding,
	) {
		const contentFormItem = isc.BizUtil._getContentFormItem(binding);
		if (contentFormItem) {
			isc.BizUtil._setContentFormItemValue(
				contentFormItem,
				contentId,
				mediaKind,
			);
		} else {
			const opener = isc.WindowStack.getOpener();
			if (opener && opener._vm) {
				if (mediaKind && companionBinding) {
					opener._vm.setValue(companionBinding, mediaKind);
				}
				opener._vm.setValue(binding, contentId);
			}
		}
		isc.WindowStack.popoff(false);
		delete isc.BizUtil._contentFormItemsByBinding[binding];
	},

	afterMarkupApply: function (binding, contentId, modoc, fileName) {
		const contentFormItem = isc.BizUtil._getContentFormItem(binding);
		if (contentFormItem) {
			isc.BizUtil._setContentFormItemValue(contentFormItem, contentId, "image");
		} else {
			const opener = isc.WindowStack.getOpener();
			if (opener && opener._vm) {
				opener._vm.setValue(binding, contentId);
			}
		}
		isc.WindowStack.popoff(false);
		delete isc.BizUtil._contentFormItemsByBinding[binding];
	},

	/**
	 * Creates an upload button.
	 * @param {Object} contentFormItem - the form item for the upload.
	 * @param {boolean} image - whether the upload is for an image.
	 * @param {boolean} showMarkup - whether markup is enabled.
	 * @param {string} [uploadNoun] - the noun used in upload menu labels.
	 * @returns {Object} - the created upload button.
	 */
	createUploadButton: function (contentFormItem, image, showMarkup, uploadNoun) {
		const messageSuffix = isc.BizUtil._contentUploadMessageSuffix(
			uploadNoun,
			image,
		);
		const menu = [
			{
				title:
					isc.i18nMessages[
						"bizUtilSplitButton_UploadButtonClear" +
							messageSuffix +
							"Title"
					],
				icon: "icons/delete.png",
				click: () => {
					contentFormItem.setValue(null);
					if (contentFormItem.companion) {
						contentFormItem.form._view._vm.setValue(contentFormItem.companion, null);
					}
				},
				enableIf: () => contentFormItem.getValue() !== null,
			},
		];

		if (showMarkup) {
			const markupAvailable = () =>
				!contentFormItem.isMarkupAvailable ||
				contentFormItem.isMarkupAvailable();
			menu.push({
				title: isc.i18nMessages.bizUtilSplitButton_UploadMarkupImageTitle,
				icon: "icons/edit.png",
				click: function () {
					if (!contentFormItem.getValue() || !markupAvailable()) {
						return;
					}
					isc.BizUtil._registerContentFormItem(contentFormItem);
					const instance = contentFormItem.form._view.gather(false);
					let url = `imageMarkup.xhtml?_n=${SKYVE.Util.unsanitiseBinding(
						contentFormItem.name,
					)}&_c=${instance._c}&_id=${contentFormItem.getValue()}`;
					if (contentFormItem.form._view._b) {
						url += `&_b=${SKYVE.Util.unsanitiseBinding(contentFormItem.form._view._b)}`;
					}
					isc.WindowStack.popup(
						null,
						isc.i18nMessages.bizUtilSplitButton_UploadMarkupImageTitle,
						true,
						[
							isc.HTMLPane.create({
								contentsType: "page",
								contents: "Loading Page...",
								contentsURL: url,
							}),
						],
					);
				},
				enableIf: () =>
					contentFormItem.getValue() !== null && markupAvailable(),
				hiddenIf: () => !markupAvailable(),
			});
		}

		return isc.BizUtil.createSplitButton(
			isc.i18nMessages.bizUtilSplitButton_UploadButtonTitle,
			null,
			false,
			isc.i18nMessages[
				"bizUtilSplitButton_UploadButton" + messageSuffix + "Tooltip"
			],
			function () {
				isc.BizUtil.openContentUpload(contentFormItem, image, uploadNoun);
			},
			isc.i18nMessages.bizUtilSplitButton_UploadTooltip,
			null,
			menu,
			85,
			"left",
		);
	},

	/**
	 * Gets an edit view for a module and document.
	 * @param {string} moduleName - the module name.
	 * @param {string} documentName - the document name.
	 * @param {Function} onViewCreated - the callback when the view is created.
	 */
	getEditView: function (moduleName, documentName, onViewCreated) {
		if (!isc.BizUtil._modules[moduleName]) {
			isc.BizUtil._modules[moduleName] = {};
			window[moduleName] = {};
		}

		const documentEntry = isc.BizUtil._modules[moduleName][documentName];
		if (documentEntry) {
			const view =
				documentEntry._unused.pop() ||
				eval(`${moduleName}.create${documentName}()`);
			view._moduleName = moduleName;
			view._documentName = documentName;
			documentEntry._used.push(view);
			onViewCreated(view);
		} else {
			isc.RPCManager.sendRequest({
				showPrompt: true,
				evalResult: true,
				httpMethod: "GET",
				actionURL: `${SKYVE.Util.CONTEXT_URL}smartgen?_mod=${moduleName}&_doc=${documentName}`,
				callback: function () {
					isc.BizUtil._modules[moduleName][documentName] = {
						_used: [],
						_unused: [],
					};
					isc.BizUtil.getEditView(moduleName, documentName, onViewCreated);
				},
			});
		}
	},

	/**
	 * Relinquishes an edit view.
	 * @param {Object} view - the view to relinquish.
	 */
	relinquishEditView: function (view) {
		const documentEntry =
			isc.BizUtil._modules[view._moduleName][view._documentName];
		documentEntry._used.remove(view);
		documentEntry._unused.push(view);
	},

	/**
	 * Gets a pick list.
	 * @param {Object} lookupDescription - the lookup description.
	 * @param {Array} filterParams - the filter parameters.
	 * @param {Object} view - the associated view.
	 * @returns {Object} - the pick list.
	 */
	getPickList: function (lookupDescription, filterParams, view) {
		const result =
			isc.BizUtil._unusedPickLists.pop() ||
			isc.BizListGrid.create({ isPickList: true });
		result.setLookup(lookupDescription, filterParams, view);
		return result;
	},

	/**
	 * Relinquishes a pick list.
	 * TODO - Why arent the fields defined when I used a cached BizListGrid?
	 * @param {Object} pickList - the pick list to relinquish.
	 */
	relinquishPickList: function (pickList) {
		pickList.destroy();
	},

	/**
	 * Creates a list grid.
	 * @returns {Object} - the created list grid.
	 */
	createListGrid: function () {
		return isc.BizListGrid.create({ margin: 2 });
	},

	/**
	 * Creates a calendar.
	 * @returns {Object} - the created calendar.
	 */
	createCalendar: function () {
		return isc.Calendar.create({
			width: "100%",
			height: "100%",
			scrollToWorkDay: true,
			data: [],
		});
	},

	/**
	 * Creates a tree grid.
	 * @returns {Object} - the created tree grid.
	 */
	createTreeGrid: function () {
		return isc.BizListGrid.create({ margin: 2, isTree: true });
	},

	/**
	 * Creates a map.
	 * @returns {Object} - the created map.
	 */
	createMap: function () {
		return isc.BizMap.create();
	},

	/**
	 * Opens a popup frame.
	 * @param {string} url - the URL to open.
	 * @param {string} name - the name of the popup.
	 * @param {number} width - the width of the popup.
	 * @param {number} height - the height of the popup.
	 */
	popupFrame: function (url, name, width, height) {
		const win = window.open(
			url,
			name,
			`width=${width},height=${height},resizable=yes,scrollbars=no,toolbar=no,location=no,directories=no,status=yes,menubar=no,copyhistory=no`,
		);
		win.focus();
	},

	/**
	 * Displays growl notifications.
	 * The SAIL recorder (src/js/sail/recorder-sc.js) wraps this method to note the growls shown: keep its arguments.
	 * The page has one PrimeFaces Growl, which removes the messages it shows when it shows new ones, unless told to keep
	 * them.
	 * @param {Array} msgs - the messages to display.
	 * @param {number} life - the duration of the notification.
	 * @param {boolean} sticky - whether the notification is sticky.
	 * @param {boolean} [keep] - whether to keep the messages already showing, rather than replace them.
	 */
	growl: function (msgs, life, sticky, keep) {
		PrimeFaces.cw("Growl", "growl", {
			id: "growl",
			widgetVar: "growl",
			life: life || 6000,
			sticky: sticky || false,
			keepAlive: keep || false,
			msgs,
		});
	},

	/**
	 * Handles push messages.
	 * A pushed growl is added to the growls showing: it arrives on its own schedule, such as a job's when it finishes, and
	 * must not remove a growl the user has not read yet, such as the "started" growl of the action that started the job.
	 * PrimeFaces pages show pushed growls in a growl of their own for the same reason.
	 * @param {Array} pushMessage - the push messages to handle.
	 */
	onPushMessage: function (pushMessage) {
		const growls = [];
		const messages = [];
		let warn = false;

		pushMessage.forEach((m) => {
			if (m.type === "g") {
				growls.push({ severity: m.severity, summary: m.message });
			} else if (m.type === "m") {
				if (m.severity !== "info") warn = true;
				messages.push(m.message);
			} else if (m.type === "r") {
				const view = isc.BizUtil.getCurrentView();
				if (view && view.rerender) view.rerender();
			} else if (m.type === "j") {
				window[m.method](m.argument);
			}
		});

		if (growls.length > 0) isc.BizUtil.growl(growls, null, null, true);
		if (messages.length > 0) {
			const markup =
				messages.length > 1
					? `<ul>${messages.map((msg) => `<li>${msg}</li>`).join("")}</ul>`
					: messages[0];
			if (warn) isc.warn(markup);
			else isc.say(markup);
		}
	},
});

/**
 * Makes a filter on a date time or timestamp column whose converter shows only the date (a *_DateTime type) mean the
 * whole local day, as the Vue list grid does: equals is from the day's start up to the next day's, notEqual is outside
 * it (or no value), lessThan is before the day, greaterThan after it (lessOrEqual and greaterOrEqual likewise),
 * between is after the start day and before the end day, and betweenInclusive from the start day's start to the end
 * day's end. The column's filter gives the day's local midnight; without this, the server compares that instant
 * exactly.
 */
isc.RestDataSource.addMethods({
	skyveTransformRequest: isc.RestDataSource.getPrototype().transformRequest,

	/**
	 * Turns the day filters of a fetch's criteria into ranges, then transforms the request as RestDataSource does.
	 *
	 * @param {Object} dsRequest - the request.
	 * @returns {Object} - the transformed request data.
	 */
	transformRequest: function (dsRequest) {
		if (dsRequest.operationType === "fetch") {
			dsRequest.data = isc.BizUtil.dataSourceDayCriteria(this, dsRequest.data, dsRequest.textMatchStyle);
		}
		return this.skyveTransformRequest(dsRequest);
	},
});

isc.BizUtil.addClassMethods({
	/**
	 * Returns the criteria with each clause on a day field of the data source (see RestDataSource.transformRequest
	 * above) made the range of that local day. A request that sends a list grid's criteria other than through the data
	 * source's fetch (export, chart, tag and untag) converts them with this too, so that it means the rows shown.
	 *
	 * @param {Object} dataSource - the data source.
	 * @param {Object} criteria - simple or advanced criteria, or nothing.
	 * @param {string} textMatchStyle - the text match style for simple criteria; "substring" when not given, as the
	 *   export, chart and tag servlets match simple criteria.
	 * @returns {Object} - the criteria.
	 */
	dataSourceDayCriteria: function (dataSource, criteria, textMatchStyle) {
		if (!criteria || isc.isAn.emptyObject(criteria)) {
			return criteria;
		}
		const dayFields = isc.BizUtil.dayFields(dataSource);
		return dayFields.length > 0 ? isc.BizUtil.dayCriteria(criteria, dayFields, textMatchStyle) : criteria;
	},

	/**
	 * Returns the names of a data source's day fields: its date times and timestamps whose converter shows only the
	 * date (a *_DateTime type).
	 *
	 * @param {Object} dataSource - the data source.
	 * @returns {Array} - the field names, empty when it has none.
	 */
	dayFields: function (dataSource) {
		return (dataSource.getFieldNames() || []).filter((name) => {
			const type = dataSource.getField(name).type;
			return isc.isA.String(type) && type.endsWith("_DateTime");
		});
	},

	/**
	 * Returns the criteria with each clause on a day field (see RestDataSource.transformRequest above) whose value (or
	 * start or end, for a between) is a date made the range of those local days. Criteria without such a clause are
	 * returned as they are.
	 *
	 * @param {Object} criteria - simple or advanced criteria.
	 * @param {Array} dayFields - the names of the fields filtered by the day.
	 * @param {string} textMatchStyle - the request's text match style, for simple criteria.
	 * @returns {Object} - the criteria.
	 */
	dayCriteria: function (criteria, dayFields, textMatchStyle) {
		const ranges = ["between", "iBetween", "betweenInclusive", "iBetweenInclusive"];
		const onDay = (clause) =>
			dayFields.includes(clause.fieldName) &&
			(ranges.includes(clause.operator)
				? isc.isA.Date(clause.start) || isc.isA.Date(clause.end)
				: isc.isA.Date(clause.value));
		let advanced = criteria;
		if (!isc.DataSource.isAdvancedCriteria(criteria)) {
			if (!Object.keys(criteria).some((name) => onDay({ fieldName: name, value: criteria[name] }))) {
				return criteria;
			}
			advanced = isc.DataSource.convertCriteria(criteria, textMatchStyle || "substring");
		}
		const startOf = (day) => new Date(day.getFullYear(), day.getMonth(), day.getDate());
		const nextAfter = (day) => new Date(day.getFullYear(), day.getMonth(), day.getDate() + 1);
		const convert = (clause) => {
			if (clause.criteria) {
				return { ...clause, criteria: clause.criteria.map(convert) };
			}
			if (!onDay(clause)) {
				return clause;
			}
			const compare = (operator, value) => ({ fieldName: clause.fieldName, operator: operator, value: value });
			const day = clause.value;
			switch (clause.operator) {
				case "equals":
					return { operator: "and", criteria: [compare("greaterOrEqual", startOf(day)), compare("lessThan", nextAfter(day))] };
				case "notEqual": // also a row with no value, as a negation is
					return {
						operator: "or",
						criteria: [
							compare("lessThan", startOf(day)),
							compare("greaterOrEqual", nextAfter(day)),
							{ fieldName: clause.fieldName, operator: "isNull" },
						],
					};
				case "lessThan":
					return compare("lessThan", startOf(day));
				case "lessOrEqual":
					return compare("lessThan", nextAfter(day));
				case "greaterThan":
					return compare("greaterOrEqual", nextAfter(day));
				case "greaterOrEqual":
					return compare("greaterOrEqual", startOf(day));
				case "between":
				case "iBetween":
				case "betweenInclusive":
				case "iBetweenInclusive": {
					// As SmartClient compares a date column's days: between is after the start day and before the end day,
					// betweenInclusive from the start of the start day to the end of the end day. A missing end is open.
					const inclusive = clause.operator.endsWith("Inclusive");
					const bounds = [];
					if (isc.isA.Date(clause.start)) {
						bounds.push(compare("greaterOrEqual", inclusive ? startOf(clause.start) : nextAfter(clause.start)));
					}
					if (isc.isA.Date(clause.end)) {
						bounds.push(compare("lessThan", inclusive ? nextAfter(clause.end) : startOf(clause.end)));
					}
					return { operator: "and", criteria: bounds };
				}
				default:
					return clause;
			}
		};
		return convert(advanced);
	},
});

isc.BizUtil.addClassMethods({
	/**
	 * Returns the editor a type's values are filtered with when it differs from the type's editor (a SimpleType's
	 * filterEditorType), or null.
	 *
	 * @param {string} type - the type's name.
	 * @returns {string|null} - the editor's class name.
	 */
	filterEditorType: function (type) {
		const simpleType = type ? isc.SimpleType.getType(type) : null;
		return (simpleType && simpleType.filterEditorType) || null;
	},

	/**
	 * Returns whether a list grid's filter row may filter: false when an item holds a number its converter refuses
	 * (see the end of types.js), which then shows an error, so that the grid does not filter without the value.
	 *
	 * @param {Object} grid - the list grid.
	 * @returns {boolean} - true to filter.
	 */
	filterEditorAccepts: function (grid) {
		const editor = grid.filterEditor;
		const form = editor && editor.getEditForm ? editor.getEditForm() : null;
		if (!form) {
			return true;
		}
		let result = true;
		form.getItems().forEach((item) => {
			if (item._refusedText) {
				result = false;
				const integer = item.isA("BizIntegerSeparatorItem") || item.isA("BizSimplePercentageItem");
				editor.setFieldError(0, item.name, integer ? isc.Validator.notAnInteger : isc.Validator.notADecimal);
			} else if (editor.cellHasErrors(0, item.name)) {
				editor.setFieldError(0, item.name, null);
			}
		});
		return result;
	},
});
